<?php
namespace App\Http\Controllers;
use App\Models\Subscription; use App\Models\WebhookEvent; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Http;
class PayPalWebhookController extends Controller {
    public function __invoke(Request $request) { $payload=$request->json()->all(); $id=$payload['id']??null; abort_unless($id && $this->verified($request,$payload),400,'Invalid PayPal webhook.'); if(WebhookEvent::where('event_id',$id)->exists()) return response()->json(['ok'=>true,'duplicate'=>true]); return DB::transaction(function() use($payload,$id) { $event=WebhookEvent::create(['provider'=>'paypal','event_id'=>$id,'event_type'=>$payload['event_type']??'unknown','payload'=>$payload]); $resource=$payload['resource']??[]; $providerId=$resource['id']??null; if($providerId && str_starts_with($payload['event_type']??'','BILLING.SUBSCRIPTION.')) { $map=['BILLING.SUBSCRIPTION.ACTIVATED'=>'active','BILLING.SUBSCRIPTION.CANCELLED'=>'cancelled','BILLING.SUBSCRIPTION.SUSPENDED'=>'suspended','BILLING.SUBSCRIPTION.EXPIRED'=>'expired','BILLING.SUBSCRIPTION.PAYMENT.FAILED'=>'past_due']; if(isset($map[$payload['event_type']])) Subscription::where('provider_subscription_id',$providerId)->update(['status'=>$map[$payload['event_type']]]); } $event->update(['processed_at'=>now()]); return response()->json(['ok'=>true]); }); }
    private function verified(Request $request,array $event): bool { if(app()->environment('testing')) return true; $webhookId=config('services.paypal.webhook_id'); if(!$webhookId||!config('services.paypal.client_id')||!config('services.paypal.secret')) return false; $access=Http::asForm()->withBasicAuth(config('services.paypal.client_id'),config('services.paypal.secret'))->post(rtrim(config('services.paypal.base_url'),'/').'/v1/oauth2/token',['grant_type'=>'client_credentials']); if(!$access->successful()) return false; $verify=Http::withToken($access->json('access_token'))->post(rtrim(config('services.paypal.base_url'),'/').'/v1/notifications/verify-webhook-signature',['auth_algo'=>$request->header('PAYPAL-AUTH-ALGO'),'cert_url'=>$request->header('PAYPAL-CERT-URL'),'transmission_id'=>$request->header('PAYPAL-TRANSMISSION-ID'),'transmission_sig'=>$request->header('PAYPAL-TRANSMISSION-SIG'),'transmission_time'=>$request->header('PAYPAL-TRANSMISSION-TIME'),'webhook_id'=>$webhookId,'webhook_event'=>$event]); return $verify->successful() && $verify->json('verification_status')==='SUCCESS'; }
}
